CREATE DATABASE IF NOT EXISTS yishijie;\nUSE yishijie;\n\nCREATE TABLE user (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  username VARCHAR(100) UNIQUE NOT NULL,\n  password VARCHAR(255) NOT NULL,\n  phone VARCHAR(20) UNIQUE NOT NULL,\n  real_name VARCHAR(100) NOT NULL,\n  wechat_open_id VARCHAR(255) UNIQUE,\n  age INT DEFAULT 0,\n  gender VARCHAR(20) DEFAULT 'M',\n  health_info TEXT,\n  health_score INT DEFAULT 0,\n  integral_score INT DEFAULT 0,\n  promotion_count INT DEFAULT 0,\n  promotion_reward DECIMAL(10,2) DEFAULT 0,\n  status INT DEFAULT 0,\n  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n);\n\nCREATE TABLE course (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  name VARCHAR(200) NOT NULL,\n  description TEXT,\n  cover TEXT,\n  price DECIMAL(10,2) NOT NULL,\n  teacher VARCHAR(100) NOT NULL,\n  duration INT DEFAULT 0,\n  enroll_count INT DEFAULT 0,\n  max_enroll INT DEFAULT 0,\n  status VARCHAR(20) DEFAULT 'ACTIVE',\n  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n);\n\nCREATE TABLE orders (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  user_id BIGINT NOT NULL,\n  order_no VARCHAR(100) UNIQUE NOT NULL,\n  type INT DEFAULT 0,\n  total_amount DECIMAL(10,2) NOT NULL,\n  status INT DEFAULT 0,\n  remark TEXT,\n  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY(user_id) REFERENCES user(id)\n);\n\nCREATE TABLE health_record (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  user_id BIGINT NOT NULL UNIQUE,\n  age INT DEFAULT 0,\n  blood_type VARCHAR(20),\n  medical_history TEXT,\n  family_history TEXT,\n  health_score INT DEFAULT 0,\n  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY(user_id) REFERENCES user(id)\n);\n\nCREATE TABLE promotion_info (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT,\n  user_id BIGINT NOT NULL UNIQUE,\n  promotion_code VARCHAR(100) UNIQUE NOT NULL,\n  referral_count INT DEFAULT 0,\n  total_reward DECIMAL(10,2) DEFAULT 0,\n  status VARCHAR(20) DEFAULT 'ACTIVE',\n  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY(user_id) REFERENCES user(id)\n);